CREATE PROCEDURE [dbo].[Recalculate_Agent_Bill_Total] @T_ID INT AS BEGIN SET NOCOUNT ON;
DECLARE @BsType_ID INT, @DetailsTotal DECIMAL(18,3) = 0, @Discount DECIMAL(18,3) = 0, @Pure DECIMAL(18,3) = 0;
------------------------------------------------------------------- -- جلب نوع الفاتورة والخصم الحالي من الهيدر ------------------------------------------------------------------- SELECT @BsType_ID = BsType_ID, @Discount = ISNULL(Discount, 0) FROM Agents_Balance_MV WHERE T_ID = @T_ID;
IF @BsType_ID IS NULL BEGIN RAISERROR(N'لم يتم العثور على الفاتورة في الجدول الرئيسي Agents_Balance_MV', 16, 1); RETURN; END
------------------------------------------------------------------- -- تحديد جدول التفاصيل حسب نوع المعاملة ------------------------------------------------------------------- IF @BsType_ID = 1 BEGIN -- فاتورة مبيعات SELECT @DetailsTotal = ISNULL(SUM(ISNULL(T_Price, 0)), 0) FROM SB_Contents WHERE Bill_T_ID = @T_ID; END ELSE IF @BsType_ID = 2 BEGIN -- فاتورة صروفات SELECT @DetailsTotal = ISNULL(SUM(ISNULL(Total, 0)), 0) FROM EXP_Details WHERE IMEX_T_ID = @T_ID; END ELSE IF @BsType_ID = 7 BEGIN -- فاتورة مشتريات SELECT @DetailsTotal = SUM((Org_Price * QYT)) --ISNULL(SUM(ISNULL(Total, 0)), 0) FROM Pch_Details WHERE Pch_T_ID = @T_ID;
SELECT @DetailsTotal = @DetailsTotal + ISNULL(SUM([Value]),0) FROM [Pch_Exp_Values] WHERE [Pch_T_ID] = @T_ID AND [isWithBill] = 1
END ELSE IF @BsType_ID = 8 BEGIN -- فاتورة تالف SELECT @DetailsTotal = ISNULL(SUM(ISNULL(Total, 0)), 0) FROM IMEX_Details WHERE IMEX_T_ID = @T_ID; END ELSE IF @BsType_ID = 9 BEGIN -- فاتورة جرد SELECT @DetailsTotal = ISNULL(SUM(ISNULL(Total, 0)), 0) FROM Pch_Details WHERE Pch_T_ID = @T_ID; END ELSE IF @BsType_ID = 10 BEGIN -- إرجاع مبيعات SELECT @DetailsTotal = ISNULL(SUM(ISNULL(T_Price, 0)), 0) FROM Rtn_Contents WHERE Bill_T_ID = @T_ID AND Rtn_Type_ID = 1; END ELSE IF @BsType_ID = 11 BEGIN -- إرجاع مشتريات SELECT @DetailsTotal = ISNULL(SUM(ISNULL(T_Price, 0)), 0) FROM Rtn_Contents WHERE Bill_T_ID = @T_ID AND Rtn_Type_ID = 7; END ELSE IF @BsType_ID = 12 BEGIN -- إذن تحويل أصناف SELECT @DetailsTotal = ISNULL(SUM(ISNULL(Total, 0)), 0) FROM Store_Trans_Details WHERE B_T_ID = @T_ID; END ELSE IF @BsType_ID = 16 BEGIN -- فاتورة عرض SELECT @DetailsTotal = ISNULL(SUM(ISNULL(T_Price, 0)), 0) FROM ViewBill_Contents WHERE Bill_T_ID = @T_ID; END ELSE IF @BsType_ID = 17 BEGIN -- إذن صرف SELECT @DetailsTotal = ISNULL(SUM(ISNULL(Total, 0)), 0) FROM InSale_Details WHERE InSale_T_ID = @T_ID; END ELSE IF @BsType_ID = 35 BEGIN -- إذن استلام SELECT @DetailsTotal = ISNULL(SUM(ISNULL(Total, 0)), 0) FROM Outsale_Details WHERE Outsale_T_ID = @T_ID; END ELSE IF @BsType_ID = 13 or @BsType_ID = 18 BEGIN -- تصنيع SELECT @DetailsTotal = ISNULL(SUM(ISNULL(Total, 0)), 0) FROM FRM_Details WHERE FRM_T_ID = @T_ID; END ELSE IF @BsType_ID = 39 BEGIN -- تسوية محزنية SELECT @DetailsTotal = ISNULL(SUM(ISNULL(Total, 0)), 0) FROM ST_QTY_Deferences WHERE Bill_T_ID = @T_ID; END ELSE BEGIN RAISERROR(N'نوع الفاتورة غير مدعوم حاليًا في الإجراء', 16, 1); RETURN; END
------------------------------------------------------------------- -- حساب الصافي ------------------------------------------------------------------- SET @Pure = @DetailsTotal - ISNULL(@Discount, 0);
------------------------------------------------------------------- -- تحديث الجدول الرئيسي -- هنا أفترض أن Balance = Pure -- إذا لديك منطق آخر مرتبط بالمدفوعات أخبرني لنعدله ------------------------------------------------------------------- UPDATE Agents_Balance_MV SET Total = @DetailsTotal, Pure = @Pure--, --Balance = @Pure WHERE T_ID = @T_ID; END
